import {PlanetarySurfaceView} from './planetary-surface-view.js';
import {pickSurfaceTile,SURFACE_RADIUS} from './planetary-surface-grid.js';
import {M1A_TUNING as SHIP_TUNING} from './ship-data.js';
import {patchDOM} from './industry-ui.js';
import {SURVEY_TUNING as T} from './survey-data.js';
import {formatDuration} from './ship-ui.js';
import {confirmedOreAtTile} from './resource-knowledge.js';
const $=s=>document.querySelector(s),fmt=n=>n.toLocaleString('ko-KR',{notation:'compact',maximumFractionDigits:2});
const row=(name,value)=>{const p=document.createElement('p'),label=document.createElement('span'),v=document.createElement('strong');label.textContent=name;v.textContent=value;p.append(label,v);return p;};
export class SurveyUI {
 constructor({runtime,shipUI,surface,simulation,sync,notify}){
  Object.assign(this,{runtime,shipUI,surface,simulation,sync,notify});this.abort=new AbortController();this.selected=new Set();this.selecting=false;this.shipId=null;this.lastUpdate=-Infinity;this.root=document.createElement('div');this.root.className='survey-ui';this.root.innerHTML=`<aside id="survey-menu" class="survey-menu" hidden aria-label="탐사 명령"><header><strong>탐사 명령</strong><button id="survey-close" aria-label="탐사 메뉴 닫기">×</button></header><label>탐사함 <select id="survey-worker"></select></label><p id="survey-location"></p><div class="survey-actions"><button id="survey-rough">대략 탐사</button><button id="survey-choose">정밀: 섹터 지정</button><button id="survey-all">정밀: 전체 스캔</button><button id="survey-stop">탐사 중단</button></div><label><input id="survey-auto-pause" type="checkbox">탐사 완료 시 일시정지</label><div id="survey-assignments" aria-live="polite"></div></aside><div id="survey-selection" class="survey-selection" hidden><button id="survey-selection-back">← 취소</button><strong id="survey-selection-count"></strong><button id="survey-selection-confirm">탐사 확인</button></div>`;
  surface.viewer.container.parentElement.append(this.root);this.$=s=>this.root.querySelector(s);const listen=(selector,event,fn)=>this.$(selector).addEventListener(event,fn,{signal:this.abort.signal});
  for(const s of runtime.fleet.ships.values())if(s.design.surveyCapable)this.$('#survey-worker').add(new Option(s.name,s.id));
  listen('#survey-worker','change',e=>{this.shipId=e.target.value;this.updateMenu();});listen('#survey-close','click',()=>{this.cancelSelection();this.$('#survey-menu').hidden=true;});listen('#survey-rough','click',()=>this.run(()=>runtime.startRough(this.shipId)));listen('#survey-stop','click',()=>this.run(()=>runtime.cancel(this.shipId)));listen('#survey-choose','click',()=>this.choose());listen('#survey-all','click',()=>this.all());listen('#survey-auto-pause','change',e=>runtime.pauseOnCompletion=e.target.checked);listen('#survey-selection-back','click',()=>this.cancelSelection());listen('#survey-selection-confirm','click',()=>this.confirm());
  for(const type of ['pointerdown','pointerup','click','wheel','touchstart','touchmove','touchend'])this.root.addEventListener(type,e=>e.stopPropagation(),{signal:this.abort.signal,passive:true});
  document.addEventListener('keydown',e=>{if(this.selecting&&['c','escape'].includes(e.key.toLowerCase())&&!e.target.closest('input,textarea,select')){e.preventDefault();e.stopImmediatePropagation();this.cancelSelection();}},{capture:true,signal:this.abort.signal});
  $('#map-mode').addEventListener('change',()=>{if(surface.entry){surface.distributions.mode=null;surface.distributions.invalidate();}},{signal:this.abort.signal});
  this.panel=document.createElement('section');this.panel.id='survey-sector-info';this.panel.className='survey-sector-info';$('#industry-general').prepend(this.panel);surface.survey=this;shipUI.surveyUI=this;
 }
 get menuOpen(){return !this.$('#survey-menu').hidden;}
 run(fn){this.sync();try{fn();this.updateMenu();this.renderSector();this.surface.distributions.invalidate();return true;}catch(error){this.notify(error.message);return false;}}
 open(id){if(this.selecting)this.cancelSelection();try{this.runtime.explorer(id);}catch(error){this.notify(error.message);return;}this.shipId=id;this.$('#survey-worker').value=id;this.$('#survey-menu').hidden=false;this.updateMenu();}
 async showSurface(bodyId){if(this.surface.active?.bodyId!==bodyId||!this.surface.entry)await this.surface.open(bodyId);$('#map-mode').value='exploration';this.surface.administration.setMode('exploration');this.surface.distributions.mode=null;this.surface.distributions.invalidate();}
 async choose(){this.sync();const body=this.runtime.currentBody(this.shipId);if(!body){this.notify('현재 천체의 행성권에서 섹터를 지정하세요.');return;}this.bodyId=body;const zoom=this.surface.viewer.orbitZoom;this.orbitSelection= !this.surface.active&&zoom.bodyId===body&&['low','surface'].includes(zoom.layer);if(this.orbitSelection){const v=this.surface.viewer;this.selectionRadius=zoom.layer==='low'?SHIP_TUNING.orbitRadiusMultipliers.low:SURFACE_RADIUS;this.orbitSelectionView=new PlanetarySurfaceView(v.bodies.get(body),this.runtime.record(body).grid);this.orbitSelectionView.root.scale.setScalar(this.selectionRadius/SURFACE_RADIUS);this.orbitSelectionView.lines.visible=false;v.surveySelection=this;}else await this.showSurface(body);this.selected.clear();this.selecting=true;this.$('#survey-menu').hidden=true;this.$('#survey-selection').hidden=false;this.refreshSelection();}
 async all(){this.sync();const body=this.runtime.currentBody(this.shipId);if(this.run(()=>this.runtime.startPrecise(this.shipId,body,[],{all:true}))){await this.showSurface(body);this.notify('미완료 섹터를 공유 대기열에 넣었습니다. 다른 탐사함도 전체 스캔으로 합류할 수 있습니다.');}}
 pickOrbitTile(x,y){if(!this.selecting||!this.orbitSelectionView)return null;const v=this.surface.viewer,e=v.bodies.get(this.bodyId);v.setRay(x,y);e.spin.updateWorldMatrix(true,false);const ray=v.raycaster.ray.clone().applyMatrix4(e.spin.matrixWorld.clone().invert());return pickSurfaceTile(this.runtime.record(this.bodyId).grid,ray.origin,ray.direction,this.selectionRadius);}
 handleOrbitClick(x,y){if(!this.selecting||!this.orbitSelectionView)return false;this.handleTile(this.pickOrbitTile(x,y)?.tile.id??null);return true;}
 paintOrbitSelection(){const view=this.orbitSelectionView;if(!view)return;view.update(this.surface.viewer.camera,this.surface.viewer.height);view.lines.visible=false;const colors=new Map();for(const tile of view.grid.tiles){const progress=this.runtime.preciseProgress(this.bodyId,tile.id);colors.set(tile.id,this.selected.has(tile.id)?T.colors.selected:progress>=1?T.colors.complete:progress>0?T.colors.active:T.colors.unknown);}view.setAuthoringColors(colors,{opacity:.6});this.surface.distributions.legend([{color:T.colors.unknown,text:'클릭/터치하여 섹터 추가'},{color:T.colors.selected,text:'선택한 섹터'},{color:T.colors.complete,text:'정밀 완료'}],'저궤도·표면 껍질에서 직접 선택');}
 handleTile(id){if(!this.selecting)return false;if(id){this.selected.has(id)?this.selected.delete(id):this.selected.add(id);this.refreshSelection();}return true;}
 refreshSelection(){this.$('#survey-selection-count').textContent=`${this.selected.size}개 섹터 선택`;this.$('#survey-selection-confirm').disabled=!this.selected.size;if(this.orbitSelectionView)this.paintOrbitSelection();else this.surface.distributions.invalidate();}
 cancelSelection(){if(!this.selecting)return false;this.selecting=false;this.selected.clear();if(this.surface.viewer.surveySelection===this)this.surface.viewer.surveySelection=null;this.orbitSelectionView?.dispose();this.orbitSelectionView=null;if(this.orbitSelection)$('#surface-distribution-legend').hidden=true;this.orbitSelection=false;this.$('#survey-selection').hidden=true;this.$('#survey-menu').hidden=false;this.surface.distributions.invalidate();return true;}
 confirm(){const ids=[...this.selected];if(this.run(()=>this.runtime.startPrecise(this.shipId,this.bodyId,ids))){this.cancelSelection();this.$('#survey-menu').hidden=false;this.surface.selectTile(ids[0]);this.updateMenu();}}
 updateMenu(){const body=this.runtime.currentBody(this.shipId),record=body?this.runtime.catalog.bodies.get(body):null;this.$('#survey-location').textContent=record?`${record.body.name} · 대략 ${(this.runtime.roughProgress(body)*100).toFixed(1)}%`:'현재 천체 행성권 밖';for(const id of ['#survey-rough','#survey-choose','#survey-all'])this.$(id).disabled=!record;this.$('#survey-stop').disabled=!this.runtime.jobs.has(this.shipId);const lines=[];for(const [id]of this.runtime.jobs){const s=this.runtime.fleet.ships.get(id),status=this.runtime.shipStatus(id);lines.push(row(s.name,status.description));}if(!lines.length)lines.push(row('탐사함','명령 대기'));this.$('#survey-assignments').replaceChildren(...lines);}
 renderShip(ship){this.shipUI.$('#ship-survey').disabled=!ship.design.surveyCapable;const status=this.runtime.shipStatus(ship.id);if(!status)return;this.shipUI.$('#ship-state').textContent=status.description;if(!ship.plan){this.shipUI.$('#ship-progress').hidden=false;this.shipUI.$('#ship-progress span').textContent=status.description;this.shipUI.$('#ship-progress progress').value=status.progress;}}
 renderSector(){const body=this.surface.entry?.body.id,tile=this.surface.selectedId;if(!body||!tile){this.panel.hidden=true;this.lastSectorKey=null;return;}this.panel.hidden=false;const s=this.runtime.tileSummary(body,tile),known=confirmedOreAtTile(this.surface.entry.template,tile,{runtime:this.runtime.runtime});const key=JSON.stringify([s,known,this.simulation.paused,this.simulation.effectiveSpeed]);if(key===this.lastSectorKey)return;this.lastSectorKey=key;const next=document.createElement('div');const h=document.createElement('h4');h.textContent='탐사 지식 · 기본 능력';next.append(h,row('정밀 진행',fmt(s.precise*100)+'%'),row('광석 확인 잔여량',known.value===null?'미확인':fmt(known.value)+' U'),row('추정 원래 총량',fmt(s.range[0])+'–'+fmt(s.range[1])+' U'),row('가능성',this.runtime.possibility(body,tile).label),row('남은 게임 시간',s.remainingSeconds===null?'정지 · 이동/명령 대기':formatDuration(s.remainingSeconds)),row('현실 예상',this.simulation.paused?'일시정지':s.remainingSeconds===null?'대기':formatDuration(s.remainingSeconds/(10*this.simulation.effectiveSpeed))));
  for(const d of s.deposits){const box=document.createElement('div');box.className='survey-deposit';const title=document.createElement('strong');title.textContent=d.depositKind==='vein'?'광맥 · 추가 정밀 능력 필요':'표층';box.append(title,row('확인 / 품질 신뢰도',fmt(d.confirmedFraction*100)+'% / '+fmt(d.gradeConfidence*100)+'%'));const bars=document.createElement('div');bars.className='survey-grade-bars';bars.setAttribute('aria-label','저·중·고 품질 추정 확률');for(const grade of ['low','medium','high']){const span=document.createElement('span');span.className=grade;span.style.width=d.estimatedGradeProbabilities[grade]*100+'%';span.title=({low:'저',medium:'중',high:'고'}[grade])+fmt(d.estimatedGradeProbabilities[grade]*100)+'%';bars.append(span);}box.append(bars,row('저 / 중 / 고', ['low','medium','high'].map(g=>fmt(d.estimatedGradeProbabilities[g]*100)+'%').join(' / ')),row('채굴 접근',d.miningReasons.length?d.miningReasons.join(' · '):'현재 채굴 단계·깊이 기준 내'));next.append(box);}
  next.append(row('수소원',({unknown:'미확인',possible:'천체에 수소원 가능성 있음',detected:'존재 탐지 · 미확정',confirmed:'확정', 'confirmed-zero':'확인된 없음'})[s.hydrogen.status]));if(s.status==='confirmed-zero')next.append(row('조사 결과','현재 탐사 능력 기준 확인된 0'));const note=document.createElement('small');note.textContent='심부 탐사는 연구 후 개방됩니다. 범위는 원래 총량 추정이며 채굴 잔여량과 구별합니다.';next.append(note);patchDOM(this.panel,next);
 }
 distribution(view){if(!this.surface.entry||$('#map-mode').value!=='exploration'||this.surface.distributions.mode&&!this.selecting)return false;const colors=new Map(),body=this.surface.entry.body.id;for(const t of this.surface.entry.grid.tiles){const s=this.runtime.tileSummary(body,t.id),assigned=[...this.runtime.jobs.values()].some(j=>j.bodyId===body&&j.tileId===t.id),rank=this.runtime.possibility(body,t.id).rank;let color=s.status==='confirmed-zero'?T.colors.zero:s.precise>=1?T.colors.complete:assigned||s.precise>0?T.colors.active:s.rough>0?[T.colors.nearlyNone,T.colors.low,T.colors.normal,T.colors.high][rank]:T.colors.unknown;if(this.selecting&&this.selected.has(t.id))color=T.colors.selected;colors.set(t.id,color);}view.setAuthoringColors(colors,{opacity:.78});view.setAuthoringConnections(null);view.setFacilityOutlines(null);this.surface.distributions.legend([{color:T.colors.unknown,text:'미탐사'},{color:T.colors.high,text:'대략: 가능성 높음'},{color:T.colors.normal,text:'대략: 보통'},{color:T.colors.low,text:'대략: 낮음'},{color:T.colors.nearlyNone,text:'대략: 거의 없음'},{color:T.colors.active,text:'정밀 진행/배정'},{color:T.colors.complete,text:'기본 정밀 완료'},{color:T.colors.zero,text:'현재 능력 기준 확인된 0'}],'탐사 섹터 · 심부 미공개');return true;}
 update(now){if(now-this.lastUpdate<500)return;this.lastUpdate=now;this.updateMenu();this.renderSector();if(this.surface.entry)this.surface.distributions.invalidate();if(this.orbitSelectionView){const zoom=this.surface.viewer.orbitZoom;if(zoom.bodyId!==this.bodyId||!['low','surface'].includes(zoom.layer))this.cancelSelection();else this.paintOrbitSelection();}else if(this.selecting&&!this.surface.active)this.cancelSelection();}
 dispose(){this.cancelSelection();this.abort.abort();if(this.surface.survey===this)this.surface.survey=null;if(this.shipUI.surveyUI===this)this.shipUI.surveyUI=null;this.root.remove();this.panel.remove();}
}
